    "body": "甲、乙兩人為健身房教練，某日甲走進員工休息室，發現乙偷偷用萬能鑰匙打開甲的置物櫃，並將置物櫃內的皮夾拿走，在乙關上置物櫃之際，甲大聲吼叫「你偷拿什麼東西？」乙嚇了一跳拔腿就跑。甲從後追乙，在追上乙時立刻撲上去，將乙撲倒，乙反手抵抗，甲隨手拿起手邊的啞鈴朝乙的手臂打下去，造成乙的手臂骨折，甲在乙疼痛無法行動時，奪回自己的皮夾。試問甲之行為如何論罪？（25分）",
